package com.reldoapp;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ReldoPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ReldoPlugin.class);
		RuneLite.main(args);
	}
}

package com.reldoapp;

public enum League
{
	NONE("", "None (skip league sync)"),
	RAGING_ECHOES("raging_echoes", "Raging Echoes"),
	DEMONIC_PACTS("demonic_pacts", "Demonic Pacts");

	private final String leagueId;
	private final String displayName;

	League(String leagueId, String displayName)
	{
		this.leagueId = leagueId;
		this.displayName = displayName;
	}

	public String getLeagueId()
	{
		return leagueId;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.reldoapp;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("reldo")
public interface ReldoConfig extends Config
{
	@ConfigSection(
		name = "Connection",
		description = "Settings for connecting to your Reldo instance",
		position = 0
	)
	String connectionSection = "connection";

	@ConfigItem(
		keyName = "apiToken",
		name = "API Token",
		description = "Generate this in Reldo → Settings → Plugin API Token",
		secret = true,
		section = connectionSection,
		position = 1
	)
	default String apiToken()
	{
		return "";
	}

@ConfigSection(
		name = "Sync",
		description = "What to sync and when",
		position = 10
	)
	String syncSection = "sync";

	@ConfigItem(
		keyName = "syncOnLogin",
		name = "Sync on login",
		description = "Automatically sync when you log in",
		section = syncSection,
		position = 11
	)
	default boolean syncOnLogin()
	{
		return true;
	}

	@ConfigItem(
		keyName = "activeLeague",
		name = "Active League",
		description = "League to sync tasks for. Select None to skip league sync.",
		section = syncSection,
		position = 12
	)
	default League activeLeague()
	{
		return League.NONE;
	}
}

package com.reldoapp;

import com.reldoapp.sync.SyncResult;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Font;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

public class ReldoPanel extends PluginPanel
{
	private static final DateTimeFormatter TIME_FMT = DateTimeFormatter.ofPattern("HH:mm:ss");

	private final JLabel statusLabel;
	private final JButton syncButton;
	private final ReldoPlugin plugin;

	@Inject
	public ReldoPanel(ReldoPlugin plugin)
	{
		this.plugin = plugin;

		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		// Title
		JLabel title = new JLabel("Reldo Sync");
		title.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 16f));
		title.setForeground(new Color(255, 200, 0));
		title.setHorizontalAlignment(SwingConstants.CENTER);
		add(title, BorderLayout.NORTH);

		// Centre panel: status + button
		JPanel centre = new JPanel(new BorderLayout(0, 6));
		centre.setBackground(ColorScheme.DARK_GRAY_COLOR);

		statusLabel = new JLabel("Ready.");
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setHorizontalAlignment(SwingConstants.CENTER);
		centre.add(statusLabel, BorderLayout.NORTH);

		syncButton = new JButton("Sync Now");
		syncButton.setFocusPainted(false);
		syncButton.setBackground(new Color(50, 50, 50));
		syncButton.setForeground(Color.WHITE);
		syncButton.addActionListener(e ->
		{
			syncButton.setEnabled(false);
			statusLabel.setText("Syncing…");
			plugin.triggerSync();
		});
		centre.add(syncButton, BorderLayout.SOUTH);

		add(centre, BorderLayout.CENTER);

		// Footer note
		JLabel note = new JLabel("<html><center>Configure your API token<br>in the plugin settings.</center></html>");
		note.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		note.setFont(FontManager.getRunescapeSmallFont());
		note.setHorizontalAlignment(SwingConstants.CENTER);
		add(note, BorderLayout.SOUTH);
	}

	public void setStatus(String message)
	{
		statusLabel.setText(message);
		syncButton.setEnabled(true);
	}

	public void showResult(SyncResult result)
	{
		String time = LocalTime.now().format(TIME_FMT);
		if (result.isSuccess())
		{
			statusLabel.setForeground(new Color(0, 200, 83));
			statusLabel.setText("Synced at " + time);
		}
		else
		{
			statusLabel.setForeground(new Color(220, 50, 50));
			statusLabel.setText("<html><center>" + result.getMessage() + "</center></html>");
		}
		syncButton.setEnabled(true);
	}
}

package com.reldoapp.data;

import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Skill;

public class SkillMapper
{
	/**
	 * Collect current skill levels and XP for all skills.
	 * Keys match Reldo's hiscores.skills keys (e.g. "Attack", "Runecraft").
	 * Overall is skipped — it is computed server-side from individual skills.
	 *
	 * When in a league world, getRealSkillLevel returns the league level,
	 * so this data is correct for both main game and seasonal play.
	 *
	 * Must be called from the client thread.
	 */
	public static Map<String, Map<String, Object>> collectSkills(Client client)
	{
		Map<String, Map<String, Object>> result = new LinkedHashMap<>();
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL)
			{
				continue;
			}
			Map<String, Object> entry = new LinkedHashMap<>();
			entry.put("level", client.getRealSkillLevel(skill));
			entry.put("xp", client.getSkillExperience(skill));
			result.put(skill.getName(), entry);
		}
		return result;
	}
}

package com.reldoapp.data;

/**
 * A single collection log item entry.
 * id is -1 if the item was detected only via chat message (no widget scan yet).
 */
public class CollectionLogEntry
{
	public final int id;
	public final String name;
	public final int quantity;

	public CollectionLogEntry(int id, String name, int quantity)
	{
		this.id = id;
		this.name = name;
		this.quantity = quantity;
	}
}

