	private static Map<Integer, String> forLeague(String leagueId)
	{
		switch (leagueId)
		{
			case "raging_echoes":
				return RAGING_ECHOES;
			default:
				return null;
		}
	}

	/**
	 * Read all league task varbits for the given league and return completed task slugs.
	 * Returns null if the league is not supported. Must be called from the client thread.
	 */
	public static Map<String, Object> collectTasks(Client client, String leagueId)
	{
		Map<Integer, String> taskMap = forLeague(leagueId);
		if (taskMap == null) return null;

		Map<String, Object> result = new HashMap<>();
		for (Map.Entry<Integer, String> entry : taskMap.entrySet())
		{
			if (client.getVarbitValue(entry.getKey()) == 1)
			{
				result.put(entry.getValue(), true);
			}
		}
		return result;
	}
}

package com.reldoapp;

import com.google.inject.Provides;
import com.reldoapp.data.CombatAchievementMapper;
import com.reldoapp.data.CollectionLogTracker;
import com.reldoapp.data.DiaryMapper;
import com.reldoapp.data.LeagueTaskMapper;
import com.reldoapp.data.QuestMapper;
import com.reldoapp.data.SkillMapper;
import com.reldoapp.sync.SyncResult;
import com.reldoapp.sync.SyncService;
import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Reldo",
	description = "Sync your OSRS character data to Reldo",
	tags = {"tracker", "quests", "leagues", "diary", "reldo"}
)
public class ReldoPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ReldoConfig config;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private EventBus eventBus;

	@Inject
	private SyncService syncService;

	@Inject
	private CollectionLogTracker collectionLogTracker;

	private ReldoPanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		panel = injector.getInstance(ReldoPanel.class);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "reldo_icon.png");

		navButton = NavigationButton.builder()
			.tooltip("Reldo")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);

		// Load persisted collection log data, then register for live events
		collectionLogTracker.load();
		collectionLogTracker.setSyncCallback(() -> executor.submit(this::doCollectionLogSync));
		eventBus.register(collectionLogTracker);

		log.debug("Reldo plugin started");
	}

	@Override
	protected void shutDown()
	{
		eventBus.unregister(collectionLogTracker);

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
		panel = null;
		navButton = null;
		log.debug("Reldo plugin stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN && config.syncOnLogin())
		{
			// Delay 3s — varbits are not fully populated immediately on login
			executor.schedule(() -> clientThread.invoke(this::doSync), 3, TimeUnit.SECONDS);
		}
	}

	/**
	 * Trigger a full sync from outside the client thread (e.g., panel button click).
	 */
	void triggerSync()
	{
		clientThread.invoke(this::doSync);
	}

	/**
	 * Collect all game state on the client thread, then fire the HTTP call on the executor.
	 * Must be called from the client thread.
	 */
	private void doSync()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			SwingUtilities.invokeLater(() -> panel.setStatus("Not logged in."));
			return;
		}

		String playerName = client.getLocalPlayer().getName();
		if (playerName == null || playerName.isEmpty())
		{
			SwingUtilities.invokeLater(() -> panel.setStatus("Could not read player name."));
			return;
		}

		SwingUtilities.invokeLater(() -> panel.setStatus("Syncing…"));

		// Collect all game data while on the client thread
		Map<String, Object> payload = new LinkedHashMap<>();
		payload.put("character_name", playerName);
		payload.put("skills", SkillMapper.collectSkills(client));
		payload.put("quests", QuestMapper.collectQuests(client));
		payload.put("achievement_diaries", DiaryMapper.collectDiaries(client));
		payload.put("combat_achievements", CombatAchievementMapper.collectCombatAchievements(client));

		// Include accumulated collection log data
		List clItems = collectionLogTracker.getItems();
		if (!clItems.isEmpty())
		{
			payload.put("collection_log", Map.of("items", clItems));
		}

		League league = config.activeLeague();
		if (league != League.NONE)
		{
			String leagueId = league.getLeagueId();
			Map<String, Object> taskMap = LeagueTaskMapper.collectTasks(client, leagueId);
			if (taskMap != null)
			{
				Map<String, Object> leaguePayload = new LinkedHashMap<>();
				leaguePayload.put("tasks", taskMap);
				leaguePayload.put("skills", SkillMapper.collectSkills(client));
				payload.put("leagues", Map.of(leagueId, leaguePayload));
			}
		}

		// Hand off to background thread for the HTTP call
		executor.submit(() ->
		{
			SyncResult result = syncService.send(payload);
			SwingUtilities.invokeLater(() -> panel.showResult(result));
		});
	}

	/**
	 * Send only the collection log payload immediately after a new item is obtained
	 * or the collection log UI is browsed. Lightweight — no client thread reads needed.
	 */
	private void doCollectionLogSync()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		String playerName = client.getLocalPlayer() != null
			? client.getLocalPlayer().getName()
			: null;
		if (playerName == null || playerName.isEmpty())
		{
			return;
		}

		List clItems = collectionLogTracker.getItems();
		if (clItems.isEmpty())
		{
			return;
		}

		Map<String, Object> payload = new LinkedHashMap<>();
		payload.put("character_name", playerName);
		payload.put("collection_log", Map.of("items", clItems));

		syncService.send(payload); // already on executor thread via callback
	}

	@Provides
	ReldoConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ReldoConfig.class);
	}
}

package com.reldoapp.sync;

import com.google.gson.Gson;
import com.reldoapp.ReldoConfig;
import java.io.IOException;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
public class SyncService
{
	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
	private static final String SYNC_URL = "https://www.reldoapp.com/api/plugin_sync.php";

	@Inject
	private OkHttpClient httpClient;

	@Inject
	private ReldoConfig config;

	@Inject
	private Gson gson;

	/**
	 * Send the collected payload to Reldo's plugin sync endpoint.
	 * Must be called from a background thread (not the client thread).
	 */
	public SyncResult send(Map<String, Object> payload)
	{
		String token = config.apiToken().trim();
		if (token.isEmpty())
		{
			return SyncResult.error("No API token set. Generate one in Reldo Settings.");
		}

		String body = gson.toJson(payload);

		Request request = new Request.Builder()
			.url(SYNC_URL)
			.header("Authorization", "Bearer " + token)
			.put(RequestBody.create(JSON, body))
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.isSuccessful())
			{
				return SyncResult.ok();
			}

			String responseBody = response.body() != null ? response.body().string() : "";
			log.warn("Reldo sync failed: HTTP {} — {}", response.code(), responseBody);

			if (response.code() == 401)
			{
				return SyncResult.error("Invalid API token.");
			}
			if (response.code() == 404)
			{
				return SyncResult.error("Character not found. Add it in Reldo first.");
			}
			return SyncResult.error("Sync failed (HTTP " + response.code() + ").");
		}
		catch (IOException e)
		{
			log.warn("Reldo sync error", e);
			return SyncResult.error("Network error: " + e.getMessage());
		}
	}
}

package com.reldoapp.sync;

import lombok.Value;

@Value
public class SyncResult
{
	boolean success;
	String message;

	public static SyncResult ok()
	{
		return new SyncResult(true, "Synced successfully.");
	}

	public static SyncResult error(String message)
	{
		return new SyncResult(false, message);
	}
}
